answer = []
for source in sources:
    number = source['number']
    article_path = Path('article_' + number.replace(' ', '_') + '.xml')
    entry = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    entry.update(
        proposed_xml=article_path.read_text().strip(),
        reason=editorial[number]['reason'],
        review_notes=editorial[number]['review_notes'],
        status='rewrite_draft',
    )
    answer.append(entry)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answer)} articles')
